package com.serhat.autosub.cortaja.ui;
import android.view.View; import android.view.ViewGroup; import android.widget.Button; import android.widget.LinearLayout; import android.widget.TextView; import androidx.annotation.NonNull; import androidx.annotation.Nullable; import androidx.fragment.app.Fragment; import com.serhat.autosub.models.ModelsFragment;
public class CortaJaSettingsFragment extends Fragment { @Nullable @Override public View onCreateView(@NonNull android.view.LayoutInflater i,@Nullable ViewGroup c,@Nullable android.os.Bundle b){ LinearLayout l=new LinearLayout(requireContext()); l.setOrientation(LinearLayout.VERTICAL); l.setPadding(28,22,28,20); TextView h=new TextView(requireContext()); h.setText("Configurações"); h.setTextSize(26); l.addView(h); l.addView(section("Cortes")); l.addView(section("Legendas")); l.addView(section("Vídeo")); l.addView(section("IA Local")); Button models=new Button(requireContext()); models.setText("Modelos de IA"); models.setOnClickListener(v -> requireActivity().getSupportFragmentManager().beginTransaction().replace(com.serhat.autosub.R.id.contentHost,new ModelsFragment()).addToBackStack("modelos").commit()); l.addView(models); l.addView(section("Armazenamento")); l.addView(section("Desempenho")); l.addView(section("Diagnóstico")); return l; } private TextView section(String s){TextView t=new TextView(requireContext());t.setText(s);t.setTextSize(17);t.setPadding(0,16,0,8);return t;} }
